'use client';

import { useId, useState } from 'react';
import type { ReactNode } from 'react';
import './testimonial-slider.css';

export interface TestimonialSliderItem {
  id: string;
  quote: string;
  name: string;
  role: string;
  company?: string;
  portrait?: ReactNode;
  metric?: { value: string; label: string };
}

export interface TestimonialSliderProps {
  items: TestimonialSliderItem[];
  title?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  className?: string;
}

/** Client stories that advance only when a visitor asks. Portraits are decorative. */
export function TestimonialSlider({
  items,
  title = 'In our clients’ words.',
  defaultValue,
  onValueChange,
  className = '',
}: TestimonialSliderProps) {
  const instanceId = useId();
  const [selectedId, setSelectedId] = useState(defaultValue ?? items[0]?.id);
  const foundIndex = items.findIndex((item) => item.id === selectedId);
  const index = foundIndex < 0 ? 0 : foundIndex;
  const item = items[index];
  const titleId = `${instanceId}-title`;
  const storyId = `${instanceId}-story`;

  function select(nextIndex: number) {
    const next = items[(nextIndex + items.length) % items.length];
    if (!next || next.id === item?.id) return;
    setSelectedId(next.id);
    onValueChange?.(next.id);
  }

  return (
    <section
      className={`ac-proof ${className}`.trim()}
      aria-roledescription="carousel"
      aria-labelledby={title ? titleId : undefined}
      aria-label={title ? undefined : 'Client stories'}
    >
      {title && <h3 className="ac-proof-title" id={titleId}>{title}</h3>}
      <div className="ac-proof-stage" id={storyId} aria-live="polite" aria-atomic="true">
        {item ? (
          <figure className="ac-proof-story" key={item.id}>
            <div className="ac-proof-portrait" aria-hidden="true">
              {item.portrait ?? <span className="ac-proof-initial">{Array.from(item.name.trim())[0] ?? '✳'}</span>}
            </div>
            <blockquote className="ac-proof-quote"><p>{item.quote}</p></blockquote>
            <figcaption className="ac-proof-credit">
              <span className="ac-proof-name">{item.name}</span>
              <span className="ac-proof-role">{item.role}{item.company ? `, ${item.company}` : ''}</span>
              {item.metric && <span className="ac-proof-metric"><strong>{item.metric.value}</strong><span>{item.metric.label}</span></span>}
            </figcaption>
          </figure>
        ) : <p className="ac-proof-empty">No client stories yet.</p>}
      </div>
      {item && (
        <div className="ac-proof-controls" role="group" aria-label="Choose a client story">
          <div className="ac-proof-paging">
            <button className="ac-proof-arrow" type="button" aria-label="Previous client story" aria-controls={storyId} disabled={items.length < 2} onClick={() => select(index - 1)}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="M19 12H5m6-6-6 6 6 6" /></svg>
            </button>
            <span className="ac-proof-count" aria-hidden="true">{String(index + 1).padStart(2, '0')}<span>/ {String(items.length).padStart(2, '0')}</span></span>
            <button className="ac-proof-arrow" type="button" aria-label="Next client story" aria-controls={storyId} disabled={items.length < 2} onClick={() => select(index + 1)}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" /></svg>
            </button>
          </div>
          <div className="ac-proof-dots">
            {items.map((entry, entryIndex) => (
              <button
                key={entry.id}
                type="button"
                className="ac-proof-dot"
                aria-label={`Show story ${entryIndex + 1} of ${items.length}: ${entry.name}${entry.company ? ` from ${entry.company}` : ''}`}
                aria-pressed={entryIndex === index}
                aria-controls={storyId}
                onClick={() => select(entryIndex)}
              ><span aria-hidden="true" /></button>
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

.ac-proof, .ac-proof * { box-sizing: border-box; }
.ac-proof { --ac-proof-surface: var(--ac-proof-theme-surface, #eeeade); --ac-proof-ink: var(--ac-proof-theme-ink, #292c25); --ac-proof-muted: var(--ac-proof-theme-muted, #66685e); --ac-proof-accent: #d15a3f; --ac-proof-portrait: #c6d2b8; width: 100%; min-width: 0; padding: 28px; display: flex; flex-direction: column; gap: 24px; container-type: inline-size; background: var(--ac-proof-surface); color: var(--ac-proof-ink); font-family: inherit; }
.ac-proof-title { margin: 0; max-width: 20ch; font: inherit; font-size: clamp(25px, 4.6cqw, 36px); font-weight: 500; line-height: 1.08; letter-spacing: -.055em; text-wrap: balance; }
.ac-proof-stage { flex: 1; min-width: 0; display: grid; }
.ac-proof-story { margin: 0; display: grid; grid-template-columns: minmax(120px, .72fr) minmax(0, 1fr); grid-template-rows: 1fr auto; gap: 26px; animation: ac-proof-arrive 260ms ease-out both; }
.ac-proof-portrait { grid-column: 1; grid-row: 1 / 3; min-width: 0; min-height: 230px; display: grid; place-items: center; overflow: hidden; background: var(--ac-proof-portrait); border-radius: 3px 3px 56px 3px; }
.ac-proof-portrait > :not(.ac-proof-initial) { display: block; width: 100%; height: 100%; object-fit: cover; }
.ac-proof-initial { font-size: clamp(70px, 15cqw, 145px); font-family: Georgia, serif; line-height: 1; opacity: .75; }
.ac-proof-quote { grid-column: 2; margin: 0; min-width: 0; align-self: center; }
.ac-proof-quote p { margin: 0; font: inherit; font-size: clamp(21px, 3.6cqw, 30px); font-weight: 400; letter-spacing: -.035em; line-height: 1.28; overflow-wrap: anywhere; }
.ac-proof-quote p::before { content: '“'; }
.ac-proof-quote p::after { content: '”'; }
.ac-proof-credit { grid-column: 2; display: flex; flex-direction: column; gap: 5px; min-width: 0; align-self: end; }
.ac-proof-name { font-size: 14px; font-weight: 650; line-height: 1.35; }
.ac-proof-role { color: var(--ac-proof-muted); font-size: 12px; line-height: 1.45; }
.ac-proof-metric { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-top: 12px; padding-top: 12px; border-top: 1px solid color-mix(in srgb, var(--ac-proof-ink) 18%, transparent); }
.ac-proof-metric strong { color: var(--ac-proof-accent); font-size: 24px; line-height: 1.1; font-weight: 500; letter-spacing: -.04em; }
.ac-proof-metric > span { font-size: 11px; color: var(--ac-proof-muted); }
.ac-proof-controls { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; border-top: 1px solid color-mix(in srgb, var(--ac-proof-ink) 18%, transparent); padding-top: 12px; }
.ac-proof-paging { display: flex; align-items: center; gap: 12px; }
.ac-proof-arrow, .ac-proof-dot { appearance: none; font: inherit; color: inherit; cursor: pointer; padding: 0; display: grid; place-items: center; touch-action: manipulation; }
.ac-proof-arrow { width: 44px; height: 44px; border: 1px solid color-mix(in srgb, var(--ac-proof-ink) 26%, transparent); border-radius: 50%; background: transparent; transition: background 160ms, color 160ms; }
.ac-proof-arrow svg { width: 21px; height: 21px; }
.ac-proof-arrow:disabled { opacity: .35; cursor: default; }
.ac-proof-arrow:not(:disabled):hover { color: var(--ac-proof-surface); background: var(--ac-proof-ink); }
.ac-proof-arrow:focus-visible, .ac-proof-dot:focus-visible { outline: 2px solid var(--ac-proof-accent); outline-offset: 3px; }
.ac-proof-count { display: flex; align-items: baseline; gap: 5px; font-size: 12px; font-variant-numeric: tabular-nums; }
.ac-proof-count span { font-size: 10px; color: var(--ac-proof-muted); }
.ac-proof-dots { display: flex; flex-wrap: wrap; }
.ac-proof-dot { width: 32px; height: 44px; border: 0; background: transparent; }
.ac-proof-dot span { display: block; width: 6px; height: 6px; border-radius: 50%; background: var(--ac-proof-ink); opacity: .25; transition: opacity 160ms, transform 160ms; }
.ac-proof-dot[aria-pressed='true'] span { background: var(--ac-proof-accent); opacity: 1; transform: scale(1.4); }
.ac-proof-dot:hover span { opacity: .8; }
.ac-proof-empty { margin: 0; padding: 40px 0; color: var(--ac-proof-muted); font-size: 14px; }
@keyframes ac-proof-arrive { from { opacity: .3; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
@container (max-width: 500px) {
  .ac-proof-story { grid-template-columns: 62px minmax(0, 1fr); grid-template-rows: 1fr auto; gap: 20px 14px; }
  .ac-proof-quote { grid-column: 1 / -1; grid-row: 1; }
  .ac-proof-quote p { font-size: clamp(18px, 5.8cqw, 26px); line-height: 1.32; }
  .ac-proof-portrait { grid-row: 2; min-height: 0; height: 68px; border-radius: 2px 2px 18px 2px; }
  .ac-proof-initial { font-size: 48px; }
  .ac-proof-credit { grid-row: 2; align-self: center; }
  .ac-proof-name { font-size: 13px; }
  .ac-proof-role { font-size: 11px; }
  .ac-proof-metric { margin-top: 7px; padding-top: 7px; }
  .ac-proof-metric strong { font-size: 19px; }
  .ac-proof-metric > span { font-size: 10px; }
}
@media (prefers-reduced-motion: reduce) { .ac-proof-story { animation: none; } .ac-proof-arrow, .ac-proof-dot span { transition: none; } }

/* Neutral surfaces follow an explicit page theme; artwork and accents keep their palette. */
:where([data-theme="light"]) .ac-proof {
  --ac-proof-theme-ink: #202722;
  --ac-proof-theme-muted: #687269;
  --ac-proof-theme-surface: #fafbf8;
  color-scheme: light;
}
:where([data-theme="dark"], .dark) .ac-proof {
  --ac-proof-theme-ink: #edf2eb;
  --ac-proof-theme-muted: #a7b3a3;
  --ac-proof-theme-surface: #191e1b;
  color-scheme: dark;
}
